  const response = await fetch(`${import.meta.env.VITE_API_BASE}/api/orders`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'X-Tenant': tenantId },
    body: JSON.stringify({ orderId }),
  });
  if (!response.ok) throw new Error('Order submission failed');
  return response.json();
}"},{"id":"a0a30905-1e42-4bd5-a49e-5d47d95816c9","sourceId":"f6898920-0c47-47ca-b6ad-753b2774cebc","sourceName":"inventory-worker","revision":"ddd6e72aa0a8d32d701ac1ab4e05b01abd4eba32","path":"config/local.json","startLine":1,"endLine":6,"contentHash":"8b7fe3bb5a3227daaf68a1091915fe546c8f8fc6503e429d4b8025894ad364bb","spanHash":"6349aa25543db045212c297d44d165d6c1e5271826d81ea98ca3950c3355c8fc","text":"{
