  "environment": "local",
  "orderTopic": "orders.placed.v2",
  "consumerGroup": "order-notifications"
}

{
  "environment": "production",
  "orderTopic": "${ORDER_TOPIC}",
  "apiImage": "${ORDER_API_IMAGE_DIGEST}"
}

