Billing behavior is outside this repository set."},{"id":"c22b8d17-d693-4221-b48a-065a96210314","sourceId":"9d145733-0613-4dd6-ad37-ae53701e22e1","sourceName":"order-api","revision":"237510937b4388fc718b7e9f93869954950df1bb","path":"src/main/java/Orders.java","startLine":1,"endLine":18,"contentHash":"533356fbff3802cf2f9085bc881c774a08851267d02a4448e8cc7105feb2352c","spanHash":"fb97e2aa5ace7f6292dd5007aa417217edc8d0b828793f822b3d0666df87cf52","text":"// Synthetic transport interfaces; no actual HTTP server or Kafka driver is included.
record OrderPlaced(String orderId, String tenantId, long createdAtMillis) {}
interface EventPublisher { void publish(String topic, String key, OrderPlaced event); }
record Accepted(String orderId) {}

final class Orders {
  private final EventPublisher publisher;
  private final String topic;
  Orders(EventPublisher publisher, String configuredTopic) {
    this.publisher = publisher;
    this.topic = System.getenv().getOrDefault("ORDER_TOPIC", configuredTopic);
  }
  Accepted accept(String orderId, String tenantId) {
    var event = new OrderPlaced(orderId, tenantId, System.currentTimeMillis());
    publisher.publish(topic, tenantId + ":" + orderId, event);
    return new Accepted(orderId);
  }
}"},{"id":"26f9a3f3-9337-417c-8799-0d8072c3c78c","sourceId":"fedf9c9d-1241-4ace-9445-84d2f453cd9a","sourceName":"order-worker","revision":"211aa99e97ae82bda0ef69e3d4b7954abab5eb37","path":"src/main/java/OrderConsumer.java","startLine":1,"endLine":18,"contentHash":"bc2c347b007865acd3044b52dba791f7f37abd235f5c406c06b4cf2f3516dfb0","spanHash":"0857fab150aee7933a73591e087863fbe1c349649f5d10c8ab0a7a0205c870f8","text":"// Synthetic interfaces describe intent, not broker or database runtime guarantees.
record OrderPlaced(String orderId, String tenantId, long createdAtMillis) {}
record Selector(String tenantId, String orderId) {}
interface MongoCollection { void replaceOne(Selector selector, OrderPlaced document, boolean upsert); }
interface KafkaSubscriber { void subscribe(String topic, String group, OrderConsumer handler); }

final class OrderConsumer {
  private final MongoCollection collection;
  OrderConsumer(MongoCollection collection) { this.collection = collection; }
  void start(KafkaSubscriber kafka, String configuredTopic, String group) {
    var topic = System.getenv().getOrDefault("ORDER_TOPIC", configuredTopic);
    kafka.subscribe(topic, group, this);
  }
  void onMessage(OrderPlaced event) {
    var selector = new Selector(event.tenantId(), event.orderId());
    collection.replaceOne(selector, event, true);
  }
}"},{"id":"cd97087a-f72a-44db-a084-fcb5d557e377","sourceId":"53f885b0-4466-4d08-bc38-6cf09490ff9a","sourceName":"portal","revision":"603a69798dc12c3205e88d0498881b0c01079932","path":"config/local.json","startLine":1,"endLine":4,"contentHash":"37c4ae84a8ccb522960504104dc3e316ec96e96c086bee933642fcdd3fe6b608","spanHash":"67a825e39e7134139a3ce2ac0c1f29d8d0d0492996dbccd38a920ff61d6dc2e6","text":"{
