    publisher.publish(topic, tenantId + ":" + orderId, event);
    return new Accepted(orderId);
  }
}"},{"id":"d77843cf-8e37-41ae-ad3c-b8a0686407aa","sourceId":"9d145733-0613-4dd6-ad37-ae53701e22e1","sourceName":"order-api","revision":"237510937b4388fc718b7e9f93869954950df1bb","path":"contracts/OrderPlaced.json","startLine":1,"endLine":8,"contentHash":"b7226f44f281c6ee098c6d652ff33c40b32ca8954b451273c27d47a7579ddb79","spanHash":"f99a95788043b0b83a79db786345a41095f5e9db561ada837102f83635ff387e","text":"{
