    collection.replaceOne(selector, event, true);
  }
}"},{"id":"7e14d3c3-f35a-4cd9-a2f8-602284c6cf16","sourceId":"ba1841d6-8011-48e6-94e4-ab3236e7bb3b","sourceName":"database-migrations","revision":"d75867701ea1a0a3b103a9eecc9d7532c11c9058","path":"migrations/001-orders.js","startLine":1,"endLine":3,"contentHash":"594a3329546cd338ee2af89b6b20ce970d8b8da2ac984e60e111bb6505a45571","spanHash":"fe2a04c6976050087f310667710eefa537dbb7bc189ee2db262f7784ef9fc477","text":"export async function up(client) {
